<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$message='';$newToken=null;if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){Security::requireCsrf($_POST['_csrf']??null);$appId=(int)($_POST['application_id']??0);$action=(string)($_POST['action']??'create_inbound');try{if(in_array($action,['sync_outbound','schedule_outbound'],true)){$cid=(int)$_POST['connector_id'];$connector=$db->one('SELECT * FROM scim_connectors WHERE id=?',[$cid]);if(!$connector||!$appAdmins->canManage((int)$user['id'],(int)$connector['application_id'],'manage_scim'))throw new RuntimeException('Brak uprawnień.');if($action==='sync_outbound'){$r=$scimOutbound->sync($cid,(int)$user['id']);$message='<pre class="code">'.Web::e(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>';}else{$minutes=max(0,min(10080,(int)($_POST['sync_interval_minutes']??15)));if($minutes>0&&$minutes<5)$minutes=5;$map=json_decode((string)($connector['mapping_json']??''),true);$map=is_array($map)?$map:[];$map['sync_interval_minutes']=$minutes;$db->execute('UPDATE scim_connectors SET mapping_json=? WHERE id=?',[json_encode($map,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),$cid]);$audit->write('scim.schedule.updated','success',(int)$user['id'],null,(int)$connector['application_id'],null,['connector_id'=>$cid,'minutes'=>$minutes]);$scheduler->refreshDiscoveredJobs();$message='<div class="alert success">Harmonogram SCIM zapisany.</div>';}}else{if(!$appAdmins->canManage((int)$user['id'],$appId,'manage_scim'))throw new RuntimeException('Brak uprawnień do SCIM tej aplikacji.');if($action==='create_outbound'){$id=$scimOutbound->createConnector($appId,trim((string)$_POST['base_url']),(string)$_POST['bearer_token'],(int)$user['id']);$minutes=max(0,min(10080,(int)($_POST['sync_interval_minutes']??15)));if($minutes>0&&$minutes<5)$minutes=5;$row=$db->one('SELECT mapping_json FROM scim_connectors WHERE id=?',[$id]);$map=json_decode((string)($row['mapping_json']??''),true);$map=is_array($map)?$map:[];$map['sync_interval_minutes']=$minutes;$db->execute('UPDATE scim_connectors SET mapping_json=? WHERE id=?',[json_encode($map,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),$id]);$scheduler->refreshDiscoveredJobs();$message='<div class="alert success">Outbound connector #'.$id.' utworzony. Token zapisano zaszyfrowany.</div>';}else{$token='scim_'.Security::randomToken(48);$db->execute("INSERT INTO scim_connectors(application_id,enabled,direction,bearer_token_hash,mapping_json) VALUES(?,1,'inbound',?,?)",[$appId,hash('sha256',$token),json_encode(['userName'=>'username','email'=>'email'],JSON_THROW_ON_ERROR)]);$id=$db->lastInsertId();$audit->write('scim.connector.created','success',(int)$user['id'],null,$appId,null,['connector_id'=>$id]);$newToken=['token'=>$token,'id'=>$id];}}}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}
$apps=$db->all('SELECT id,name FROM applications WHERE deleted_at IS NULL ORDER BY name');$appOptions='';foreach($apps as$a)if($appAdmins->canManage((int)$user['id'],(int)$a['id'],'manage_scim'))$appOptions.='<option value="'.(int)$a['id'].'">'.Web::e($a['name']).'</option>';$rows='';foreach($db->all('SELECT sc.*,a.name AS app_name FROM scim_connectors sc JOIN applications a ON a.id=sc.application_id ORDER BY sc.id DESC')as$sc){if(!$appAdmins->canManage((int)$user['id'],(int)$sc['application_id'],'manage_scim'))continue;$endpoint=$sc['direction']==='inbound'?rtrim((string)$config['issuer'],'/').'/scim/v2/'.(int)$sc['id']:(string)$sc['base_url'];$actions='';$schedule='—';if($sc['direction']==='outbound'){$map=json_decode((string)($sc['mapping_json']??''),true);$minutes=(int)(is_array($map)?($map['sync_interval_minutes']??15):15);$schedule=$minutes>0?'co '.$minutes.' min':'wyłączony';$actions='<form method="post" class="inline"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><input type="hidden" name="connector_id" value="'.(int)$sc['id'].'"><button name="action" value="sync_outbound">Synchronizuj</button><input type="number" name="sync_interval_minutes" min="0" max="10080" value="'.$minutes.'" style="width:7rem"><button name="action" value="schedule_outbound">Harmonogram</button></form>';}$rows.='<tr><td>'.Web::e($sc['app_name']).'</td><td>'.Web::e($sc['direction']).'</td><td><code>'.Web::e($endpoint).'</code></td><td>'.((bool)$sc['enabled']?'Aktywny':'Wyłączony').'</td><td>'.Web::e($sc['last_sync_at']?:'—').'</td><td>'.Web::e($schedule).'</td><td>'.$actions.'</td></tr>';}$tokenBox=$newToken?'<div class="alert warning"><strong>Bearer token — zapisz teraz.</strong><div class="code">'.Web::e($newToken['token']).'</div><p>Endpoint: <code>'.Web::e(rtrim((string)$config['issuer'],'/').'/scim/v2/'.$newToken['id']).'</code></p></div>':'';$forms='';if($appOptions!=='')$forms='<section class="card"><h2>Nowy inbound connector</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Aplikacja<select name="application_id">'.$appOptions.'</select></label><button class="primary" name="action" value="create_inbound">Utwórz connector i token</button></form></section><section class="card"><h2>Nowy outbound connector</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Aplikacja<select name="application_id">'.$appOptions.'</select></label><label>SCIM base URL HTTPS<input type="url" name="base_url" required></label><label>Bearer token<input type="password" name="bearer_token" required autocomplete="off"></label><label>Synchronizacja co N minut (0 = ręcznie)<input type="number" name="sync_interval_minutes" min="0" max="10080" value="15"></label><button class="primary" name="action" value="create_outbound">Utwórz outbound connector</button></form></section>';$content='<div class="page-head"><div><h1>SCIM 2.0</h1><p>Inbound i outbound provisioning/deprovisioning z harmonogramem.</p></div></div>'.$message.$tokenBox.$forms.'<div class="table-wrap"><table><thead><tr><th>Aplikacja</th><th>Kierunek</th><th>Endpoint</th><th>Status</th><th>Ostatni sync</th><th>Harmonogram</th><th>Akcje</th></tr></thead><tbody>'.($rows?:'<tr><td colspan="7">Brak connectorów.</td></tr>').'</tbody></table></div>';Web::page('SCIM 2.0',$content,$user);
